package com.mavric.health.persistence.sqlserver;
import java.util.*;
import java.math.*;
import java.time.*;
import java.util.function.Supplier;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.ApiException;
/** Explicit read adapter, not a bean. Executor and REQUIRED manager must share the future runtime datasource.
 * V6 owns dynamic membership/module/readers authorization; Java does not filter definitions or cases. */
public final class SqlServerWorkflowStore {
 private final SqlServerExecutor executor;private final TransactionTemplate transactions;
 public SqlServerWorkflowStore(SqlServerExecutor executor,PlatformTransactionManager manager){this.executor=Objects.requireNonNull(executor);this.transactions=new TransactionTemplate(Objects.requireNonNull(manager));}
 private <T>T within(Supplier<T> work){try{return transactions.execute(tx->work.get());}catch(RuntimeException failure){throw SqlServerErrors.map(failure);}}
 private static SqlServerContext authority(HttpServletRequest req){if(req==null)throw SqlServerErrors.database();Object host=req.getAttribute("health.tenant");if(host!=null && !(host instanceof TenantRef))throw SqlServerErrors.database();if(!(req.getAttribute("health.actor") instanceof Actor actor) || !(host instanceof TenantRef tenant) || actor.tenantId()==null || !actor.tenantId().equals(tenant.id()))throw ApiException.forbidden();if(actor.roles()==null)throw SqlServerErrors.database();if(actor.roles().contains("SAD") || actor.roles().contains("SOP"))throw ApiException.forbidden();var c=SqlServerRequestContexts.from(req,SqlServerContext.Scope.REQUEST);if(!canonical(c.actorId()) || !canonical(c.tenantId()) || c.tokenHash()==null || !c.tokenHash().matches("[a-fA-F0-9]{64}"))throw SqlServerErrors.database();return c;}

 public List<Map<String,Object>> definitions(HttpServletRequest request){return within(()->{var c=authority(request);return rows(executor.execute(SqlServerProcedure.WORKFLOW_DEFINITIONS,c),false).stream().map(SqlServerWorkflowStore::definition).toList();});}
 public List<Map<String,Object>> list(HttpServletRequest request,String type){return within(()->{var c=authority(request);if(type==null || type.isBlank() || type.length()>60)throw SqlServerErrors.invalid();return rows(executor.execute(SqlServerProcedure.WORKFLOW_LIST,c,type),true).stream().map(row->item(row,c.tenantId(),type)).toList();});}
 private static List<Map<String,Object>> rows(SqlServerExecutor.Result result,boolean limited){if(result==null || result.resultSets().size()!=1 || limited&&result.resultSets().getFirst().size()>200)throw SqlServerErrors.database();return result.resultSets().getFirst();}
 private static Map<String,Object> definition(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();out.put("type",text(row,"type",60));out.put("module",text(row,"module",40));out.put("patientRequired",bit(row,"patientRequired"));out.put("animalOnly",bit(row,"animalOnly"));for(String key:List.of("creators","operators","readers"))out.put(key,roles(row,key));out.put("transitions",json(field(row,"transitions"),Collections.newSetFromMap(new IdentityHashMap<>())));return Collections.unmodifiableMap(out);}
 private static List<String> roles(Map<String,Object> row,String key){if(!(field(row,key) instanceof List<?> values))throw SqlServerErrors.database();var copy=new ArrayList<String>();for(Object item:values){if(!(item instanceof String role) || !Set.of("ADM","PRO","ASI","REC","CAJ","ALM","FAR","DIA","AUD","PAC","RES").contains(role))throw SqlServerErrors.database();copy.add(role);}return Collections.unmodifiableList(copy);}
 private static Map<String,Object> item(Map<String,Object> row,String tenant,String type){var out=new LinkedHashMap<String,Object>();for(String key:List.of("id","tenantId","branchId","actorId"))out.put(key,id(row,key));if(!tenant.equals(out.get("tenantId")))throw SqlServerErrors.database();out.put("patientId",nullableId(row,"patientId"));String returnedType=text(row,"type",60);if(!type.equals(returnedType))throw SqlServerErrors.database();out.put("type",returnedType);out.put("status",text(row,"status",40));out.put("title",text(row,"title",200));out.put("payload",json(field(row,"payload"),Collections.newSetFromMap(new IdentityHashMap<>())));if(!(field(row,"revision") instanceof Integer revision) || revision<1)throw SqlServerErrors.database();out.put("revision",revision);out.put("createdAt",time(row,"createdAt",false));out.put("updatedAt",time(row,"updatedAt",false));return Collections.unmodifiableMap(out);}
 private static Boolean bit(Map<String,Object> row,String key){if(!(field(row,key) instanceof Boolean value))throw SqlServerErrors.database();return value;}
 private static String nullableId(Map<String,Object> row,String key){Object value=field(row,key);if(value==null)return null;if(!(value instanceof String id) || !canonical(id))throw SqlServerErrors.database();return id;}
 private static Object field(Map<String,Object> row,String key){if(row==null || !row.containsKey(key))throw SqlServerErrors.database();return row.get(key);}
 private static String text(Map<String,Object> row,String key,int max){if(!(field(row,key) instanceof String value) || value.length()>max)throw SqlServerErrors.database();return value;}
 private static boolean canonical(String value){if(value==null)return false;try{return UUID.fromString(value).toString().equals(value);}catch(IllegalArgumentException invalid){return false;}}
 private static String id(Map<String,Object> row,String key){String value=text(row,key,36);if(!canonical(value))throw SqlServerErrors.database();return value;}
 private static String time(Map<String,Object> row,String key,boolean nullable){Object value=field(row,key);if(value==null && nullable)return null;if(!(value instanceof String text))throw SqlServerErrors.database();try{Instant time=Instant.parse(text);if(!text.endsWith("Z") || time.getNano()%1000!=0 || time.isBefore(Instant.parse("0001-01-01T00:00:00Z")) || time.isAfter(Instant.parse("9999-12-31T23:59:59.999999Z")))throw SqlServerErrors.database();}catch(DateTimeException invalid){throw SqlServerErrors.database();}return text;}
 private static Object json(Object value,Set<Object> ancestors){if(value==null || value instanceof String || value instanceof Boolean || value instanceof Byte || value instanceof Short || value instanceof Integer || value instanceof Long || value instanceof BigInteger || value instanceof BigDecimal)return value;if(value instanceof Double n && Double.isFinite(n) || value instanceof Float f && Float.isFinite(f))return value;if(!(value instanceof Map<?,?>) && !(value instanceof List<?>) || !ancestors.add(value))throw SqlServerErrors.database();try{if(value instanceof List<?> list){var copy=new ArrayList<Object>();for(Object item:list)copy.add(json(item,ancestors));return Collections.unmodifiableList(copy);}var copy=new LinkedHashMap<String,Object>();((Map<?,?>)value).forEach((key,item)->{if(!(key instanceof String name))throw SqlServerErrors.database();copy.put(name,json(item,ancestors));});return Collections.unmodifiableMap(copy);}finally{ancestors.remove(value);}}
 @Override public String toString(){return "SqlServerWorkflowStore[redacted]";}
}
